    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);
        if(request==11){if(result==RESULT_OK)configureWidget();else cancelWidget();return;}if(request==12){if(result==RESULT_OK)finishWidget();else cancelWidget();return;}if(result!=RESULT_OK||data==null)return;
        if(request==30){ArrayList<String> phrases=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(phrases!=null&&!phrases.isEmpty())webSearch(phrases.get(0));return;}
        Uri uri=data.getData();if(uri==null)return;
        try{if(request==32){getContentResolver().takePersistableUriPermission(uri,data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION));fileBrowser=new FileBrowser(this,uri);fileBrowser.show();}
            else if(request==31){open(new Intent(Intent.ACTION_VIEW).setDataAndType(uri,getContentResolver().getType(uri)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}
            else if(request==20){getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);store.put("wallpaper_uri",uri.toString());loadWallpaper();}
            else if(request==21){try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){out.write(pendingExport.getBytes(java.nio.charset.StandardCharsets.UTF_8));}toast("Export saved");}
            else if(request==22){String json=readDocument(uri);if(importingPreset){applyPreset(presetGroup,json);toast("Glass preset imported");render();}else new AlertDialog.Builder(this).setTitle("Restore Aura layout?").setMessage("This replaces your launcher settings, pages, folders and dock. Existing widget bindings and wallpaper are retained; exported widget providers must be added again on a new device.").setPositiveButton("Restore",(d,w)->{try{store.restore(json);refreshApps();toast("Layout restored");}catch(Exception e){toast("Could not restore: "+e.getMessage());}}).setNegativeButton("Cancel",null).show();}
        }catch(Exception e){toast("Could not complete the file action: "+e.getMessage());}
    }
